using ComplianceCaseManagement.Cases;
namespace ComplianceCaseManagement.EscalationWorker; public sealed class EscalationWorker(IServiceScopeFactory scopes, ILogger<EscalationWorker> log) : BackgroundService { protected override async Task ExecuteAsync(CancellationToken ct) { using var timer = new PeriodicTimer(TimeSpan.FromMinutes(1)); do { try { await using var scope = scopes.CreateAsyncScope(); var count = await scope.ServiceProvider.GetRequiredService<CaseService>().EscalateAsync("system:deadline-worker", ct); log.LogInformation("Escalated {CaseCount} overdue cases", count); } catch (Exception e) when (e is not OperationCanceledException) { log.LogError(e, "Deadline evaluation failed"); } } while (await timer.WaitForNextTickAsync(ct)); } }
